118	/** A generic instance of a plain Python class (only `object()` is supported). */
119	export class PyObject {
120	  constructor(clsName = 'builtins.object') {
121	    this.clsName = clsName;
122	    this.dict = new PyDict();
123	  }
124	}
125	
126	/** A callable implemented in JS. */
127	export class PyBuiltin {
128	  constructor(name, fn) {
129	    this.name = name;
130	    this.fn = fn;
131	  }
132	}
133	
134	/** A user `lambda`. */
135	export class PyFunction {
136	  constructor(name, params, body, closure) {
137	    this.name = name;
138	    this.params = params;
139	    this.body = body;
140	    this.closure = closure;
141	  }
142	}
143	
144	/** A bound method: `obj.meth` */
145	export class PyBoundMethod {
146	  constructor(name, self, fn) {
147	    this.name = name;
148	    this.self = self;
149	    this.fn = fn;
150	  }
151	}
