153	/* ------------------------------------------------------------------ *
154	 * Hashing (dict / set key identity)
155	 * ------------------------------------------------------------------ */
156	
157	/**
158	 * Produce a string that is equal for two Python values exactly when
159	 * `a == b and hash(a) == hash(b)` holds in CPython for hashable values.
160	 * Notably 1, 1.0 and True collapse to the same key.
161	 */
162	export function hashKey(v) {
163	  if (typeof v === 'string') return 's�' + v;
164	  if (typeof v === 'bigint') return numericKey(v);
165	  if (typeof v === 'number') return numericKey(v);
166	  if (v instanceof PyBool) return numericKey(v.value ? 1n : 0n);
167	  if (v instanceof PyNone) return 'N';
168	  if (v instanceof PyEllipsis) return 'E';
169	  if (v instanceof PyBytes) {
170	    let s = 'b�';
171	    for (const b of v.bytes) s += String.fromCharCode(b);
172	    return s;
173	  }
174	  if (v instanceof PyTuple) {
175	    let s = 't�(';
176	    for (const it of v.items) s += hashKey(it) + '';
177	    return s + ')';
178	  }
179	  if (v instanceof PyFrozenSet) {
180	    const parts = v.keyOrder().slice().sort();
181	    return 'F�(' + parts.join('') + ')';
182	  }
183	  if (v instanceof PyComplex) return 'c�' + numericKey(v.re) + '' + numericKey(v.im);
184	  if (v instanceof PyRange || v instanceof PyBuiltin || v instanceof PyFunction ||
185	      v instanceof PyObject || v instanceof PyBoundMethod) {
186	    return 'o�' + objectId(v);
187	  }
188	  if (v instanceof PyList) typeError("unhashable type: 'list'");
189	  if (v instanceof PyDict) typeError("unhashable type: 'dict'");
190	  if (v instanceof PySet) typeError("unhashable type: 'set'");
191	  return 'o�' + objectId(v);
192	}
193	
194	function numericKey(x) {
195	  if (typeof x === 'bigint') return 'n�' + x.toString();
196	  // Number: unify integral doubles with the matching int.
197	  if (Number.isFinite(x) && Number.isInteger(x)) return 'n�' + BigInt(x).toString();
198	  if (Number.isNaN(x)) return 'f�nan�' + objectIdOfNaN(x);
199	  if (x === Infinity) return 'f�inf';
200	  if (x === -Infinity) return 'f�-inf';
201	  return 'f�' + x.toString();
202	}
203	
204	// Each distinct NaN object in a dict stays distinct in CPython because
205	// `nan != nan`; approximate by making every NaN key unique.
206	let nanCounter = 0;
207	const nanIds = new WeakMap();
208	function objectIdOfNaN() {
209	  return 'nan' + ++nanCounter;
210	}
211	
212	let idCounter = 0;
213	const idMap = new WeakMap();
214	/** Stable per-object identity, standing in for CPython's `id()`. */
215	export function objectId(o) {
216	  if (o === null || (typeof o !== 'object' && typeof o !== 'function')) return 'v' + String(o);
217	  let v = idMap.get(o);
218	  if (v === undefined) {
219	    v = ++idCounter;
220	    idMap.set(o, v);
221	  }
222	  return v;
223	}
224	
225	/* ------------------------------------------------------------------ *
226	 * dict / set
227	 * ------------------------------------------------------------------ */
228	
229	export class PyDict {
230	  constructor(entries = []) {
231	    /** @type {Map<string, [any, any]>} insertion ordered */
232	    this.map = new Map();
233	    for (const [k, v] of entries) this.set(k, v);
234	  }
235	  get size() {
236	    return this.map.size;
237	  }
238	  has(k) {
239	    return this.map.has(hashKey(k));
240	  }
241	  get(k, dflt = undefined) {
242	    const e = this.map.get(hashKey(k));
243	    return e === undefined ? dflt : e[1];
244	  }
245	  set(k, v) {
246	    const h = hashKey(k);
247	    const e = this.map.get(h);
248	    if (e === undefined) this.map.set(h, [k, v]);
249	    else e[1] = v; // CPython keeps the original key object
250	  }
251	  delete(k) {
252	    return this.map.delete(hashKey(k));
253	  }
254	  /** @returns {Array<[any, any]>} */
255	  entries() {
256	    return Array.from(this.map.values(), (e) => [e[0], e[1]]);
257	  }
258	  keys() {
259	    return Array.from(this.map.values(), (e) => e[0]);
260	  }
261	  values() {
262	    return Array.from(this.map.values(), (e) => e[1]);
263	  }
264	}
265	
266	export class PySet {
267	  constructor(items = []) {
268	    this.map = new Map();
269	    for (const it of items) this.add(it);
270	  }
271	  get size() {
272	    return this.map.size;
273	  }
274	  add(v) {
275	    const h = hashKey(v);
276	    if (!this.map.has(h)) this.map.set(h, v);
277	  }
278	  has(v) {
279	    return this.map.has(hashKey(v));
280	  }
281	  delete(v) {
282	    return this.map.delete(hashKey(v));
283	  }
284	  values() {
285	    return Array.from(this.map.values());
286	  }
287	  keyOrder() {
288	    return Array.from(this.map.keys());
289	  }
290	}
291	
292	export class PyFrozenSet extends PySet {}
293	
294	/* ------------------------------------------------------------------ *
295	 * Type names / truthiness / equality / ordering
296	 * ------------------------------------------------------------------ */
297	
298	export function typeName(v) {
299	  if (typeof v === 'string') return 'str';
300	  if (typeof v === 'bigint') return 'int';
301	  if (typeof v === 'number') return 'float';
302	  if (v instanceof PyBool) return 'bool';
303	  if (v instanceof PyNone) return 'NoneType';
304	  if (v instanceof PyEllipsis) return 'ellipsis';
305	  if (v instanceof PyBytes) return 'bytes';
306	  if (v instanceof PyList) return 'list';
307	  if (v instanceof PyTuple) return 'tuple';
308	  if (v instanceof PyFrozenSet) return 'frozenset';
309	  if (v instanceof PySet) return 'set';
310	  if (v instanceof PyDict) return 'dict';
311	  if (v instanceof PyComplex) return 'complex';
312	  if (v instanceof PyRange) return 'range';
313	  if (v instanceof PySlice) return 'slice';
314	  if (v instanceof PyBuiltin) return 'builtin_function_or_method';
315	  if (v instanceof PyFunction) return 'function';
316	  if (v instanceof PyBoundMethod) return 'builtin_function_or_method';
317	  if (v instanceof PyObject) return 'object';
318	  return 'object';
319	}
320	
321	export function truthy(v) {
322	  if (v instanceof PyBool) return v.value;
323	  if (v instanceof PyNone) return false;
324	  if (typeof v === 'bigint') return v !== 0n;
325	  if (typeof v === 'number') return v !== 0;
326	  if (typeof v === 'string') return v.length > 0;
327	  if (v instanceof PyBytes) return v.bytes.length > 0;
328	  if (v instanceof PyList || v instanceof PyTuple) return v.items.length > 0;
329	  if (v instanceof PySet || v instanceof PyDict) return v.size > 0;
330	  if (v instanceof PyComplex) return v.re !== 0 || v.im !== 0;
331	  if (v instanceof PyRange) return rangeLength(v) > 0n;
332	  return true;
333	}
334	
335	/** True when `v` is one of int / float / bool (numeric tower we support). */
336	export const isNumeric = (v) =>
337	  typeof v === 'bigint' || typeof v === 'number' || v instanceof PyBool;
338	
339	/** Numeric value as BigInt if integral, else Number. */
340	export function numOf(v) {
341	  if (v instanceof PyBool) return v.value ? 1n : 0n;
342	  return v;
343	}
344	
345	/** Coerce a numeric to Number (float). */
346	export function toFloat(v) {
347	  const n = numOf(v);
348	  return typeof n === 'bigint' ? Number(n) : n;
349	}
350	
351	export function pyEq(a, b) {
352	  if (isNumeric(a) && isNumeric(b)) return numEq(numOf(a), numOf(b));
353	  if (a instanceof PyComplex || b instanceof PyComplex) {
354	    if (!(isNumeric(a) || a instanceof PyComplex) || !(isNumeric(b) || b instanceof PyComplex))
355	      return false;
356	    const ca = a instanceof PyComplex ? a : new PyComplex(toFloat(a), 0);
357	    const cb = b instanceof PyComplex ? b : new PyComplex(toFloat(b), 0);
358	    return ca.re === cb.re && ca.im === cb.im;
359	  }
360	  if (typeof a === 'string' || typeof b === 'string') return a === b;
361	  if (a instanceof PyNone || b instanceof PyNone) return a === b;
362	  if (a instanceof PyBytes && b instanceof PyBytes) {
363	    if (a.bytes.length !== b.bytes.length) return false;
364	    for (let i = 0; i < a.bytes.length; i++) if (a.bytes[i] !== b.bytes[i]) return false;
365	    return true;
366	  }
367	  if (a instanceof PyList && b instanceof PyList) return seqEq(a.items, b.items);
368	  if (a instanceof PyTuple && b instanceof PyTuple) return seqEq(a.items, b.items);
369	  if (a instanceof PySet && b instanceof PySet) {
370	    if (a.size !== b.size) return false;
371	    for (const k of a.keyOrder()) if (!b.map.has(k)) return false;
372	    return true;
373	  }
374	  if (a instanceof PyDict && b instanceof PyDict) {
375	    if (a.size !== b.size) return false;
376	    for (const [k, v] of a.entries()) {
377	      if (!b.has(k)) return false;
378	      if (!pyEq(b.get(k), v)) return false;
379	    }
380	    return true;
381	  }
382	  return a === b;
383	}
384	
385	function numEq(x, y) {
386	  if (typeof x === 'bigint' && typeof y === 'bigint') return x === y;
387	  if (typeof x === 'number' && typeof y === 'number') return x === y;
388	  // mixed int/float
389	  const bi = typeof x === 'bigint' ? x : y;
390	  const fl = typeof x === 'bigint' ? y : x;
391	  if (!Number.isFinite(fl)) return false;
392	  if (!Number.isInteger(fl)) return false;
393	  return BigInt(fl) === bi;
394	}
395	
396	function seqEq(a, b) {
397	  if (a.length !== b.length) return false;
398	  for (let i = 0; i < a.length; i++) if (!pyEq(a[i], b[i])) return false;
399	  return true;
400	}
401	
402	/**
403	 * Python `<`-based three-way comparison. Raises TypeError for values that
404	 * CPython refuses to order, which is what makes `sorted()` bail out inside
405	 * PyYAML's representer.
406	 */
407	export function pyCompare(a, b) {
408	  if (isNumeric(a) && isNumeric(b)) return numCompare(numOf(a), numOf(b));
409	  if (typeof a === 'string' && typeof b === 'string') return strCompare(a, b);
410	  if (a instanceof PyBytes && b instanceof PyBytes) {
411	    const x = a.bytes;
412	    const y = b.bytes;
413	    const n = Math.min(x.length, y.length);
414	    for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
415	    return x.length === y.length ? 0 : x.length < y.length ? -1 : 1;
416	  }
417	  if (a instanceof PyTuple && b instanceof PyTuple) return seqCompare(a.items, b.items);
418	  if (a instanceof PyList && b instanceof PyList) return seqCompare(a.items, b.items);
419	  typeError(
420	    "'<' not supported between instances of '" + typeName(a) + "' and '" + typeName(b) + "'"
421	  );
422	}
423	
424	function numCompare(x, y) {
425	  if (typeof x === 'bigint' && typeof y === 'bigint') return x < y ? -1 : x > y ? 1 : 0;
426	  const fx = typeof x === 'bigint' ? Number(x) : x;
427	  const fy = typeof y === 'bigint' ? Number(y) : y;
428	  if (Number.isNaN(fx) || Number.isNaN(fy)) return 1; // unordered; keeps sort total
429	  if (typeof x === 'bigint' || typeof y === 'bigint') {
430	    // Compare exactly when one side is a big integer.
431	    if (Number.isFinite(fx) && Number.isFinite(fy) &&
432	        Number.isInteger(fx) && Number.isInteger(fy)) {
433	      const bx = typeof x === 'bigint' ? x : BigInt(fx);
434	      const by = typeof y === 'bigint' ? y : BigInt(fy);
435	      return bx < by ? -1 : bx > by ? 1 : 0;
436	    }
437	  }
438	  return fx < fy ? -1 : fx > fy ? 1 : 0;
439	}
440	
441	/** Compare by Unicode code point, as CPython does. */
442	export function strCompare(a, b) {
443	  const ca = codePoints(a);
444	  const cb = codePoints(b);
445	  const n = Math.min(ca.length, cb.length);
446	  for (let i = 0; i < n; i++) if (ca[i] !== cb[i]) return ca[i] < cb[i] ? -1 : 1;
447	  return ca.length === cb.length ? 0 : ca.length < cb.length ? -1 : 1;
448	}
449	
450	function seqCompare(a, b) {
451	  const n = Math.min(a.length, b.length);
452	  for (let i = 0; i < n; i++) {
453	    if (!pyEq(a[i], b[i])) return pyCompare(a[i], b[i]);
454	  }
455	  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
456	}
457	
458	/**
459	 * Stable sort that mirrors CPython's "abandon everything on TypeError"
460	 * behaviour: if any comparison raises, the caller sees the PyError and can
461	 * fall back to the original order.
462	 */
463	export function pySorted(items, cmp = pyCompare) {
464	  const arr = items.slice();
465	  const n = arr.length;
466	  if (n < 2) return arr;
467	  // bottom-up stable merge sort
468	  let src = arr;
469	  let dst = new Array(n);
470	  for (let width = 1; width < n; width *= 2) {
471	    for (let lo = 0; lo < n; lo += 2 * width) {
472	      const mid = Math.min(lo + width, n);
473	      const hi = Math.min(lo + 2 * width, n);
474	      let i = lo;
475	      let j = mid;
476	      let k = lo;
477	      while (i < mid && j < hi) {
478	        if (cmp(src[j], src[i]) < 0) dst[k++] = src[j++];
479	        else dst[k++] = src[i++];
480	      }
481	      while (i < mid) dst[k++] = src[i++];
482	      while (j < hi) dst[k++] = src[j++];
483	    }
484	    const t = src;
485	    src = dst;
486	    dst = t;
487	  }
488	  return src;
489	}
490	
491	/* ------------------------------------------------------------------ *
492	 * Code-point helpers (Python strings are sequences of code points)
493	 * ------------------------------------------------------------------ */
494	
495	/** Split a JS string into an array of code points (numbers). */
496	export function codePoints(s) {
497	  const out = [];
498	  for (let i = 0; i < s.length; ) {
499	    const c = s.charCodeAt(i);
500	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
501	      const d = s.charCodeAt(i + 1);
502	      if (d >= 0xdc00 && d <= 0xdfff) {
503	        out.push((c - 0xd800) * 0x400 + (d - 0xdc00) + 0x10000);
504	        i += 2;
505	        continue;
506	      }
507	    }
508	    out.push(c);
509	    i += 1;
510	  }
511	  return out;
512	}
513	
514	/** Split a JS string into an array of single-code-point strings. */
515	export function chars(s) {
516	  const out = [];
517	  for (let i = 0; i < s.length; ) {
518	    const c = s.charCodeAt(i);
519	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
520	      const d = s.charCodeAt(i + 1);
521	      if (d >= 0xdc00 && d <= 0xdfff) {
522	        out.push(s.slice(i, i + 2));
523	        i += 2;
524	        continue;
525	      }
526	    }
527	    out.push(s[i]);
528	    i += 1;
529	  }
530	  return out;
531	}
532	
533	/** Python `len()` of a string: number of code points. */
534	export function strLength(s) {
535	  let n = 0;
536	  for (let i = 0; i < s.length; i++, n++) {
537	    const c = s.charCodeAt(i);
538	    if (c >= 0xd800 && c <= 0xdbff && i + 1 < s.length) {
539	      const d = s.charCodeAt(i + 1);
540	      if (d >= 0xdc00 && d <= 0xdfff) i++;
541	    }
542	  }
543	  return n;
544	}
545	
546	export function fromCodePoint(cp) {
547	  if (cp <= 0xffff) return String.fromCharCode(cp);
548	  const v = cp - 0x10000;
549	  return String.fromCharCode(0xd800 + (v >> 10), 0xdc00 + (v & 0x3ff));
550	}
551	
552	export function rangeLength(r) {
553	  const { start, stop, step } = r;
554	  if (step > 0n) return stop > start ? (stop - start + step - 1n) / step : 0n;
555	  return stop < start ? (start - stop + (-step) - 1n) / (-step) : 0n;
556	}
557	
558	export function rangeItems(r) {
559	  const out = [];
560	  const n = rangeLength(r);
561	  for (let i = 0n; i < n; i++) out.push(r.start + i * r.step);
562	  return out;
563	}
564	
565	/** UTF-8 encode a JS string (surrogate pairs handled, lone surrogates -> WTF-8). */
566	export function utf8Encode(s) {
567	  const out = [];
568	  for (const cp of codePoints(s)) {
569	    if (cp < 0x80) out.push(cp);
570	    else if (cp < 0x800) out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
571	    else if (cp < 0x10000) out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
572	    else
573	      out.push(
574	        0xf0 | (cp >> 18),
575	        0x80 | ((cp >> 12) & 0x3f),
576	        0x80 | ((cp >> 6) & 0x3f),
577	        0x80 | (cp & 0x3f)
578	      );
579	  }
580	  return new Uint8Array(out);
581	}
