/**
 * nodes.mjs — port of `yaml.nodes`.
 *
 * PyYAML represents a document as a tree of Node objects before serialising it
 * to events.  Node *object identity* is what drives anchors/aliases in the
 * serializer, so nothing here may ever collapse two distinct nodes.
 *
 * PyYAML's Node also carries `start_mark`/`end_mark`; both are `None` on the
 * dump path, so they are omitted.
 */

export class Node {
  constructor(tag, value, style = null) {
    this.tag = tag;
    this.value = value;
    this.style = style;
  }
}

/** `yaml.nodes.ScalarNode` — `.value` is a JS string, `.style` one of
 *  null (plain / chosen by the emitter), '', "'", '"', '|', '>'. */
export class ScalarNode extends Node {
  constructor(tag, value, style = null) {
    super(tag, value, style);
    this.id = 'scalar';
  }
}

/** Base of the two collection nodes; `.flowStyle` is PyYAML's `flow_style`. */
export class CollectionNode extends Node {
  constructor(tag, value, flowStyle = null) {
    super(tag, value, null);
    this.flowStyle = flowStyle;
  }
}

/** `.value` is an Array of child Nodes. */
export class SequenceNode extends CollectionNode {
  constructor(tag, value, flowStyle = null) {
    super(tag, value, flowStyle);
    this.id = 'sequence';
  }
}

/** `.value` is an Array of `[keyNode, valueNode]` pairs. */
export class MappingNode extends CollectionNode {
  constructor(tag, value, flowStyle = null) {
    super(tag, value, flowStyle);
    this.id = 'mapping';
  }
}

/* ------------------------------------------------------------------ *
 * Tag constants
 * ------------------------------------------------------------------ */

const YAML = 'tag:yaml.org,2002:';

export const TAG = {
  // core schema (implicit resolvers)
  str: YAML + 'str',
  int: YAML + 'int',
  float: YAML + 'float',
  bool: YAML + 'bool',
  null: YAML + 'null',
  timestamp: YAML + 'timestamp',
  merge: YAML + 'merge',
  value: YAML + 'value',
  yaml: YAML + 'yaml',

  // collections
  seq: YAML + 'seq',
  map: YAML + 'map',
  set: YAML + 'set',
  pairs: YAML + 'pairs',
  omap: YAML + 'omap',
  binary: YAML + 'binary',

  // python-specific tags produced by `yaml.representer.Representer`
  pythonNone: YAML + 'python/none',
  pythonBool: YAML + 'python/bool',
  pythonStr: YAML + 'python/str',
  pythonUnicode: YAML + 'python/unicode',
  pythonBytes: YAML + 'python/bytes',
  pythonInt: YAML + 'python/int',
  pythonLong: YAML + 'python/long',
  pythonFloat: YAML + 'python/float',
  pythonComplex: YAML + 'python/complex',
  pythonList: YAML + 'python/list',
  pythonTuple: YAML + 'python/tuple',
  pythonDict: YAML + 'python/dict',

  // prefixes: a dotted `module.qualname` is appended
  pythonNamePrefix: YAML + 'python/name:',
  pythonModulePrefix: YAML + 'python/module:',
  pythonObjectPrefix: YAML + 'python/object:',
  pythonObjectApplyPrefix: YAML + 'python/object/apply:',
  pythonObjectNewPrefix: YAML + 'python/object/new:',

  // fully-formed tags for the builtins we can produce
  pythonFrozenset: YAML + 'python/object/apply:builtins.frozenset',
  pythonRange: YAML + 'python/object/apply:builtins.range',
  pythonSlice: YAML + 'python/object/apply:builtins.slice',
  pythonBytearray: YAML + 'python/object/apply:builtins.bytearray',
  pythonObject: YAML + 'python/object:builtins.object',
};

/** PyYAML's `Resolver.DEFAULT_*_TAG`. */
export const DEFAULT_SCALAR_TAG = TAG.str;
export const DEFAULT_SEQUENCE_TAG = TAG.seq;
export const DEFAULT_MAPPING_TAG = TAG.map;

/**
 * events.mjs — port of `yaml.events`.
 *
 * The emitter consumes these.  PyYAML's events also carry
 * `start_mark`/`end_mark` (always `None` when dumping), so they are omitted.
 *
 * Every event exposes a `kind` string so the emitter can switch on it without
 * relying on `instanceof`; the classes are exported as well so that
 * `instanceof` keeps working.
 */

export class Event {
  constructor(kind) {
    this.kind = kind;
  }
}

/** Base of Alias / Scalar / CollectionStart — PyYAML's `NodeEvent`. */
export class NodeEvent extends Event {
  constructor(kind, anchor) {
    super(kind);
    this.anchor = anchor;
  }
}

export class CollectionStartEvent extends NodeEvent {
  constructor(kind, anchor, tag, implicit, flowStyle = null) {
    super(kind, anchor);
    this.tag = tag;
    this.implicit = implicit;
    this.flowStyle = flowStyle;
  }
}

export class CollectionEndEvent extends Event {}

/* ------------------------------------------------------------------ *
 * Concrete events
 * ------------------------------------------------------------------ */

export class StreamStartEvent extends Event {
  constructor(encoding = null) {
    super('StreamStart');
    this.encoding = encoding;
  }
}

export class StreamEndEvent extends Event {
  constructor() {
    super('StreamEnd');
  }
}

export class DocumentStartEvent extends Event {
  constructor(explicit = null, version = null, tags = null) {
    super('DocumentStart');
    this.explicit = explicit;
    this.version = version;
    this.tags = tags;
  }
}

export class DocumentEndEvent extends Event {
  constructor(explicit = null) {
    super('DocumentEnd');
    this.explicit = explicit;
  }
}

export class AliasEvent extends NodeEvent {
  constructor(anchor) {
    super('Alias', anchor);
  }
}

/** `implicit` is a two-element array `[detectedMatchesTag, defaultMatchesTag]`. */
export class ScalarEvent extends NodeEvent {
  constructor(anchor, tag, implicit, value, style = null) {
    super('Scalar', anchor);
    this.tag = tag;
    this.implicit = implicit;
    this.value = value;
    this.style = style;
  }
}

export class SequenceStartEvent extends CollectionStartEvent {
  constructor(anchor, tag, implicit, flowStyle = null) {
    super('SequenceStart', anchor, tag, implicit, flowStyle);
  }
}

export class SequenceEndEvent extends CollectionEndEvent {
  constructor() {
    super('SequenceEnd');
  }
}

export class MappingStartEvent extends CollectionStartEvent {
  constructor(anchor, tag, implicit, flowStyle = null) {
    super('MappingStart', anchor, tag, implicit, flowStyle);
  }
}

export class MappingEndEvent extends CollectionEndEvent {
  constructor() {
    super('MappingEnd');
  }
}

/* ------------------------------------------------------------------ *
 * Predicates (mirror `isinstance(event, ...)` checks in the emitter)
 * ------------------------------------------------------------------ */

export const isStreamStartEvent = (e) => e.kind === 'StreamStart';
export const isStreamEndEvent = (e) => e.kind === 'StreamEnd';
export const isDocumentStartEvent = (e) => e.kind === 'DocumentStart';
export const isDocumentEndEvent = (e) => e.kind === 'DocumentEnd';
export const isAliasEvent = (e) => e.kind === 'Alias';
export const isScalarEvent = (e) => e.kind === 'Scalar';
export const isSequenceStartEvent = (e) => e.kind === 'SequenceStart';
export const isSequenceEndEvent = (e) => e.kind === 'SequenceEnd';
export const isMappingStartEvent = (e) => e.kind === 'MappingStart';
export const isMappingEndEvent = (e) => e.kind === 'MappingEnd';

/** PyYAML `isinstance(event, (SequenceStartEvent, MappingStartEvent))`. */
export const isCollectionStartEvent = (e) =>
  e.kind === 'SequenceStart' || e.kind === 'MappingStart';

export const isCollectionEndEvent = (e) =>
  e.kind === 'SequenceEnd' || e.kind === 'MappingEnd';

/** PyYAML `isinstance(event, NodeEvent)` — alias, scalar or collection start. */
export const isNodeEvent = (e) =>
  e.kind === 'Alias' ||
  e.kind === 'Scalar' ||
  e.kind === 'SequenceStart' ||
  e.kind === 'MappingStart';

/**
 * resolver.mjs — port of `yaml.resolver.Resolver`'s implicit scalar resolution.
 *
 * PyYAML registers a list of (tag, regexp, first-characters) triples; on
 * resolve it looks up the candidate list by the scalar's FIRST character and
 * tries the candidates in REGISTRATION order, returning the first match, and
 * `tag:yaml.org,2002:str` if none matches.  The wildcard list (first char
 * `None`) is empty for the default resolver.
 *
 * Registration order (resolver.py, top to bottom):
 *     bool, float, int, merge, null, timestamp, value, yaml
 *
 * Every regexp below is transcribed into a hand-written character scanner.
 * The regexps are anchored (`^...$`), so only "does a full match exist?"
 * matters; where the original relies on backtracking (the sexagesimal
 * `(:[0-5]?[0-9])+` groups) the scanner explores both branches.
 */

import { TAG, DEFAULT_SCALAR_TAG, DEFAULT_SEQUENCE_TAG, DEFAULT_MAPPING_TAG } from './nodes.mjs';

/* ------------------------------------------------------------------ *
 * Character classes
 * ------------------------------------------------------------------ */

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9';
const isOctDigit = (c) => c !== undefined && c >= '0' && c <= '7';
const isBinDigit = (c) => c === '0' || c === '1';
const isHexDigit = (c) =>
  isDigit(c) || (c !== undefined && ((c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')));
const isDigitOrUnderscore = (c) => isDigit(c) || c === '_';
const isSign = (c) => c === '-' || c === '+';
const isSpaceOrTab = (c) => c === ' ' || c === '\t';

/** Skip an optional `[-+]`. */
const skipSign = (s, i) => (isSign(s[i]) ? i + 1 : i);

/** Skip `[0-9_]*`. */
function skipDigitsUnderscores(s, i) {
  while (i < s.length && isDigitOrUnderscore(s[i])) i++;
  return i;
}

/**
 * `(:[0-5]?[0-9])+` starting at `i`; `tail(j)` decides whether the remainder
 * of the pattern matches once the repetition stops at `j`.  Greedy: one more
 * repetition is tried before the tail, and the two-digit form before the
 * one-digit form — but every branch is explored, exactly like backtracking.
 */
function matchSexagesimalGroups(s, i, tail) {
  if (s[i] !== ':') return false;
  const d0 = s[i + 1];
  if (!isDigit(d0)) return false;
  const ends = [];
  // `[0-5]?[0-9]` — two digits when the first is 0-5, else a single digit.
  if (d0 >= '0' && d0 <= '5' && isDigit(s[i + 2])) ends.push(i + 3);
  ends.push(i + 2);
  for (const end of ends) {
    if (matchSexagesimalGroups(s, end, tail)) return true;
    if (tail(end)) return true;
  }
  return false;
}

/* ------------------------------------------------------------------ *
 * bool
 *   ^(yes|Yes|YES|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON
 *     |off|Off|OFF)$
 * ------------------------------------------------------------------ */

const BOOL_WORDS = [
  'yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF',
];

function matchBool(s) {
  for (const w of BOOL_WORDS) if (s === w) return true;
  return false;
}

/* ------------------------------------------------------------------ *
 * float
 *   ^([-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
 *    |\.[0-9_]+([eE][-+][0-9]+)?
 *    |[-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
 *    |[-+]?\.(inf|Inf|INF)
 *    |\.(nan|NaN|NAN))$
 * Note: a '.' is mandatory and the exponent's sign is mandatory, which is why
 * '1e5' is NOT a float.
 * ------------------------------------------------------------------ */

/** `([eE][-+][0-9]+)?` at `i`, then end of string. */
function matchOptionalExponentEnd(s, i) {
  if (i === s.length) return true;
  if (s[i] !== 'e' && s[i] !== 'E') return false;
  i++;
  if (!isSign(s[i])) return false;
  i++;
  if (!isDigit(s[i])) return false;
  while (i < s.length && isDigit(s[i])) i++;
  return i === s.length;
}

// [-+]?[0-9][0-9_]*\.[0-9_]*([eE][-+][0-9]+)?
function floatDecimal(s) {
  let i = skipSign(s, 0);
  if (!isDigit(s[i])) return false;
  i = skipDigitsUnderscores(s, i + 1);
  if (s[i] !== '.') return false;
  i = skipDigitsUnderscores(s, i + 1);
  return matchOptionalExponentEnd(s, i);
}

// \.[0-9_]+([eE][-+][0-9]+)?
function floatLeadingDot(s) {
  if (s[0] !== '.') return false;
  if (!isDigitOrUnderscore(s[1])) return false;
  const i = skipDigitsUnderscores(s, 2);
  return matchOptionalExponentEnd(s, i);
}

// [-+]?[0-9][0-9_]*(:[0-5]?[0-9])+\.[0-9_]*
function floatSexagesimal(s) {
  let i = skipSign(s, 0);
  if (!isDigit(s[i])) return false;
  i = skipDigitsUnderscores(s, i + 1);
  return matchSexagesimalGroups(s, i, (j) => {
    if (s[j] !== '.') return false;
    return skipDigitsUnderscores(s, j + 1) === s.length;
  });
}

// [-+]?\.(inf|Inf|INF)
function floatInf(s) {
  const i = skipSign(s, 0);
  if (s[i] !== '.') return false;
  const rest = s.slice(i + 1);
  return rest === 'inf' || rest === 'Inf' || rest === 'INF';
}

// \.(nan|NaN|NAN)
function floatNan(s) {
  if (s[0] !== '.') return false;
  const rest = s.slice(1);
  return rest === 'nan' || rest === 'NaN' || rest === 'NAN';
}

function matchFloat(s) {
  return (
    floatDecimal(s) || floatLeadingDot(s) || floatSexagesimal(s) || floatInf(s) || floatNan(s)
  );
}

/* ------------------------------------------------------------------ *
 * int
 *   ^([-+]?0b[0-1_]+
 *    |[-+]?0[0-7_]+
 *    |[-+]?(0|[1-9][0-9_]*)
 *    |[-+]?0x[0-9a-fA-F_]+
 *    |[-+]?[1-9][0-9_]*(:[0-5]?[0-9])+)$
 * ------------------------------------------------------------------ */

// [-+]?0b[0-1_]+
function intBinary(s) {
  let i = skipSign(s, 0);
  if (s[i] !== '0' || s[i + 1] !== 'b') return false;
  i += 2;
  if (!(isBinDigit(s[i]) || s[i] === '_')) return false;
  while (i < s.length && (isBinDigit(s[i]) || s[i] === '_')) i++;
  return i === s.length;
}

// [-+]?0[0-7_]+   (this is what makes '012' an int)
function intOctal(s) {
  let i = skipSign(s, 0);
  if (s[i] !== '0') return false;
  i++;
  if (!(isOctDigit(s[i]) || s[i] === '_')) return false;
  while (i < s.length && (isOctDigit(s[i]) || s[i] === '_')) i++;
  return i === s.length;
}

// [-+]?(0|[1-9][0-9_]*)
function intDecimal(s) {
  let i = skipSign(s, 0);
  if (s[i] === '0') return i + 1 === s.length;
  if (!(isDigit(s[i]) && s[i] !== '0')) return false;
  return skipDigitsUnderscores(s, i + 1) === s.length;
}

// [-+]?0x[0-9a-fA-F_]+
function intHex(s) {
  let i = skipSign(s, 0);
  if (s[i] !== '0' || s[i + 1] !== 'x') return false;
  i += 2;
  if (!(isHexDigit(s[i]) || s[i] === '_')) return false;
  while (i < s.length && (isHexDigit(s[i]) || s[i] === '_')) i++;
  return i === s.length;
}

// [-+]?[1-9][0-9_]*(:[0-5]?[0-9])+
function intSexagesimal(s) {
  let i = skipSign(s, 0);
  if (!isDigit(s[i]) || s[i] === '0') return false;
  i = skipDigitsUnderscores(s, i + 1);
  return matchSexagesimalGroups(s, i, (j) => j === s.length);
}

function matchInt(s) {
  return intBinary(s) || intOctal(s) || intDecimal(s) || intHex(s) || intSexagesimal(s);
}

/* ------------------------------------------------------------------ *
 * merge / null / value / yaml
 * ------------------------------------------------------------------ */

const matchMerge = (s) => s === '<<';
const matchNull = (s) => s === '~' || s === 'null' || s === 'Null' || s === 'NULL' || s === '';
const matchValue = (s) => s === '=';
const matchYaml = (s) => s === '!' || s === '&' || s === '*';

/* ------------------------------------------------------------------ *
 * timestamp
 *   ^([0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]
 *    |[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}([Tt]|[ \t]+)
 *     [0-9]{1,2}:[0-9]{2}:[0-9]{2}(\.[0-9]*)?
 *     ([ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?))?)$
 * ------------------------------------------------------------------ */

/** Exactly `n` digits starting at `i`; returns the new index or -1. */
function exactDigits(s, i, n) {
  for (let k = 0; k < n; k++) if (!isDigit(s[i + k])) return -1;
  return i + n;
}

/**
 * `[0-9]{1,max}` starting at `i`; greedy.  Every use is followed by a
 * non-digit requirement, so taking the maximum available is equivalent to the
 * regexp's backtracking behaviour.
 */
function boundedDigits(s, i, max) {
  let j = i;
  while (j < s.length && j - i < max && isDigit(s[j])) j++;
  return j === i ? -1 : j;
}

// [0-9]{4}-[0-9]{2}-[0-9]{2}
function timestampDate(s) {
  let i = exactDigits(s, 0, 4);
  if (i < 0 || s[i] !== '-') return false;
  i = exactDigits(s, i + 1, 2);
  if (i < 0 || s[i] !== '-') return false;
  i = exactDigits(s, i + 1, 2);
  return i === s.length;
}

// the full date+time form
function timestampDateTime(s) {
  let i = exactDigits(s, 0, 4);
  if (i < 0 || s[i] !== '-') return false;
  i = boundedDigits(s, i + 1, 2);
  if (i < 0 || s[i] !== '-') return false;
  i = boundedDigits(s, i + 1, 2);
  if (i < 0) return false;

  // ([Tt]|[ \t]+)
  if (s[i] === 'T' || s[i] === 't') {
    i++;
  } else if (isSpaceOrTab(s[i])) {
    while (i < s.length && isSpaceOrTab(s[i])) i++;
  } else {
    return false;
  }

  // [0-9]{1,2}:[0-9]{2}:[0-9]{2}
  i = boundedDigits(s, i, 2);
  if (i < 0 || s[i] !== ':') return false;
  i = exactDigits(s, i + 1, 2);
  if (i < 0 || s[i] !== ':') return false;
  i = exactDigits(s, i + 1, 2);
  if (i < 0) return false;

  // (\.[0-9]*)?
  if (s[i] === '.') {
    i++;
    while (i < s.length && isDigit(s[i])) i++;
  }

  // ([ \t]*(Z|[-+][0-9]{1,2}(:[0-9]{2})?))?
  if (i === s.length) return true;
  while (i < s.length && isSpaceOrTab(s[i])) i++;
  if (s[i] === 'Z') return i + 1 === s.length;
  if (!isSign(s[i])) return false;
  i = boundedDigits(s, i + 1, 2);
  if (i < 0) return false;
  if (i === s.length) return true;
  if (s[i] !== ':') return false;
  i = exactDigits(s, i + 1, 2);
  return i === s.length;
}

const matchTimestamp = (s) => timestampDate(s) || timestampDateTime(s);

/* ------------------------------------------------------------------ *
 * Registration table
 * ------------------------------------------------------------------ */

/** [tag, matcher, first characters] in PyYAML's registration order. */
const REGISTRATIONS = [
  [TAG.bool, matchBool, 'yYnNtTfFoO'],
  [TAG.float, matchFloat, '-+0123456789.'],
  [TAG.int, matchInt, '-+0123456789'],
  [TAG.merge, matchMerge, '<'],
  [TAG.null, matchNull, '~nN�EMPTY'], // '' handled below
  [TAG.timestamp, matchTimestamp, '0123456789'],
  [TAG.value, matchValue, '='],
  [TAG.yaml, matchYaml, '!&*'],
];

/** first character -> ordered list of [tag, matcher]. */
const RESOLVERS = new Map();

function register(tag, matcher, firstChars) {
  for (const ch of firstChars) {
    let list = RESOLVERS.get(ch);
    if (list === undefined) {
      list = [];
      RESOLVERS.set(ch, list);
    }
    list.push([tag, matcher]);
  }
}

for (const [tag, matcher, firstChars] of REGISTRATIONS) {
  if (tag === TAG.null) {
    // PyYAML registers null under list('~nN') + [''] — the empty key is what
    // makes the empty scalar resolve to !!null.
    register(tag, matcher, '~nN');
    register(tag, matcher, ['']);
  } else {
    register(tag, matcher, firstChars);
  }
}

/* ------------------------------------------------------------------ *
 * Public API
 * ------------------------------------------------------------------ */

/**
 * `Resolver.resolve(ScalarNode, value, (True, False))`.
 * Returns the implicitly detected tag, or `!!str` when nothing matches.
 */
export function resolveScalar(value) {
  const key = value === '' ? '' : value[0];
  const list = RESOLVERS.get(key);
  if (list !== undefined) {
    for (const [tag, matcher] of list) if (matcher(value)) return tag;
  }
  // The wildcard resolver list (`None` key) is empty for the default Resolver.
  return DEFAULT_SCALAR_TAG;
}

/**
 * `Resolver.resolve(ScalarNode, value, (False, True))` — the non-implicit
 * branch always falls straight through to DEFAULT_SCALAR_TAG.
 */
export function resolveScalarDefault() {
  return DEFAULT_SCALAR_TAG;
}

export function resolveSequence() {
  return DEFAULT_SEQUENCE_TAG;
}

export function resolveMapping() {
  return DEFAULT_MAPPING_TAG;
}

