input.content:
/**
 * representer.mjs — port of `yaml.representer.Representer` (the UNSAFE one,
 * i.e. what `yaml.dump` uses through `yaml.Dumper`).
 *
 * Turns a Python value into a tree of nodes.  Two things matter for byte-exact
 * output beyond the tags themselves:
 *
 *   * aliasing: every value that is not "ignored" gets an entry in
 *     `representedObjects` keyed by `id(value)`, so the SAME object appearing
 *     twice yields the SAME node object and the serializer emits an anchor and
 *     an alias.  `[[0]] * 2` is the classic case.
 *   * mapping order: `represent_mapping` sorts the (key, value) pairs and
 *     silently keeps insertion order if any comparison raises TypeError.
 *
 * `default_flow_style` is False and `default_style` is None for yaml.dump, so
 * every collection ends up block style; the `best_style` computation is kept
 * verbatim anyway (PyYAML computes it and then discards it).
 */

import {
  PyError,
  PyNone,
  PY_NONE,
  PyBool,
  PyBytes,
  PyList,
  PyTuple,
  PySet,
  PyFrozenSet,
  PyDict,
  PyComplex,
  PyRange,
  PySlice,
  PyObject,
  PyBuiltin,
  PyFunction,
  PyBoundMethod,
  objectId,
  pySorted,
  typeName,
} from '../pyvalues.mjs';
import { base64Encodebytes } from '../pyrepr.mjs';
import { ScalarNode, SequenceNode, MappingNode, TAG } from './nodes.mjs';

/* ------------------------------------------------------------------ *
 * repr() of a float — CPython `float_repr` / `%r`
 * ------------------------------------------------------------------ *
 * Shortest round-tripping digits, then:
 *   use_exp = decpt <= -4 or decpt > 16   (decpt = decimal exponent + 1)
 * Exponential form pads the exponent to at least two digits; fixed form always
 * keeps a fractional part ('2.0', not '2').
 * Kept local so this module does not depend on more of pyrepr.mjs than the
 * base64 helper.
 */
export function pyFloatRepr(x) {
  if (Number.isNaN(x)) return 'nan';
  if (x === Infinity) return 'inf';
  if (x === -Infinity) return '-inf';
  const negative = x < 0 || (x === 0 && 1 / x < 0);
  const a = negative ? -x : x;
  // toExponential() with no argument gives exactly the shortest round-trip
  // digits, formatted as d[.ddd]e{+,-}X.
  const s = a.toExponential();
  const ePos = s.indexOf('e');
  const mantissa = s.slice(0, ePos);
  const exponent = Number(s.slice(ePos + 1));
  const digits = mantissa.indexOf('.') < 0 ? mantissa : mantissa.replace('.', '');
  const decpt = exponent + 1;
  let out;
  if (decpt <= -4 || decpt > 16) {
    let m = digits[0];
    if (digits.length > 1) m += '.' + digits.slice(1);
    const e = decpt - 1;
    const eSign = e < 0 ? '-' : '+';
    let eDigits = String(e < 0 ? -e : e);
    if (eDigits.length < 2) eDigits = '0' + eDigits;
    out = m + 'e' + eSign + eDigits;
  } else if (decpt <= 0) {
    out = '0.' + '0'.repeat(-decpt) + digits;
  } else if (decpt >= digits.length) {
    out = digits + '0'.repeat(decpt - digits.length) + '.0';
  } else {
    out = digits.slice(0, decpt) + '.' + digits.slice(decpt);
  }
  return negative ? '-' + out : out;
}

/** `base64.encodebytes(data).decode('ascii')` */
function encodeBinary(data) {
  // pyrepr's helper takes the raw byte array; tolerate a PyBytes-taking
  // signature so a mismatch in the shared helper cannot break dumping.
  let out;
  try {
    out = base64Encodebytes(data.bytes);
  } catch (e) {
    out = base64Encodebytes(data);
  }
  if (typeof out !== 'string') out = base64Encodebytes(data);
  return out;
}

const isTypeError = (e) => e instanceof PyError && e.pyName === 'TypeError';

/* ------------------------------------------------------------------ *
 * Representer
 * ------------------------------------------------------------------ */

export class Representer {
  constructor() {
    /** alias key (id) -> node */
    this.representedObjects = new Map();
    /** keeps the represented objects alive, exactly like PyYAML's object_keeper */
    this.objectKeeper = [];
    this.aliasKey = null;
    this.defaultStyle = null; // yaml.dump(default_style=None)
    this.defaultFlowStyle = false; // yaml.dump(default_flow_style=False)
  }

  /** `Representer.represent(data)` minus the serialize() call. */
  represent(data) {
    return this.representData(data);
  }

  /**
   * `ignore_aliases`: None, the empty tuple and every str/bytes/bool/int/float
   * are never anchored.
   */
  ignoreAliases(data) {
    if (data instanceof PyNone) return true;
    if (data instanceof PyTuple && data.items.length === 0) return true;
    if (typeof data === 'string') return true;
    if (data instanceof PyBytes) return true;
    if (data instanceof PyBool) return true;
    if (typeof data === 'bigint') return true; // int
    if (typeof data === 'number') return true; // float
    return false;
  }

  representData(data) {
    if (this.ignoreAliases(data)) this.aliasKey = null;
    else this.aliasKey = objectId(data);
    if (this.aliasKey !== null) {
      if (this.representedObjects.has(this.aliasKey)) {
        return this.representedObjects.get(this.aliasKey);
      }
      this.objectKeeper.push(data);
    }
    return this.dispatch(data);
  }

  /* -------------------------------------------------------------- *
   * Node factories (represent_scalar / _sequence / _mapping)
   * -------------------------------------------------------------- */

  representScalar(tag, value, style = null) {
    if (style === null) style = this.defaultStyle;
    const node = new ScalarNode(tag, value, style);
    if (this.aliasKey !== null) this.representedObjects.set(this.aliasKey, node);
    return node;
  }

  representSequence(tag, items, flowStyle = null) {
    // PyYAML reads self.alias_key before recursing into the children (which
    // overwrite it).
    const aliasKey = this.aliasKey;
    const value = [];
    const node = new SequenceNode(tag, value, flowStyle);
    if (aliasKey !== null) this.representedObjects.set(aliasKey, node);
    let bestStyle = true;
    for (const item of items) {
      const nodeItem = this.representData(item);
      if (!(nodeItem instanceof ScalarNode && !nodeItem.style)) bestStyle = false;
      value.push(nodeItem);
    }
    if (flowStyle === null) {
      if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
      else node.flowStyle = bestStyle;
    }
    return node;
  }

  /**
   * `pairs` stands in for `list(mapping.items())`.  The sort compares whole
   * (key, value) tuples and is abandoned wholesale on TypeError, which is how
   * `{1: 'a', 'b': 2}` keeps its insertion order.
   */
  representMapping(tag, pairs, flowStyle = null) {
    const aliasKey = this.aliasKey;
    const value = [];
    const node = new MappingNode(tag, value, flowStyle);
    if (aliasKey !== null) this.representedObjects.set(aliasKey, node);
    let bestStyle = true;
    let items = pairs;
    try {
      const tuples = pySorted(pairs.map((p) => new PyTuple([p[0], p[1]])));
      items = tuples.map((t) => t.items);
    } catch (e) {
      if (!isTypeError(e)) throw e;
      items = pairs; // `mapping = sorted(mapping)` never completed
    }
    for (const [key, val] of items) {
      const nodeKey = this.representData(key);
      const nodeValue = this.representData(val);
      if (!(nodeKey instanceof ScalarNode && !nodeKey.style)) bestStyle = false;
      if (!(nodeValue instanceof ScalarNode && !nodeValue.style)) bestStyle = false;
      value.push([nodeKey, nodeValue]);
    }
    if (flowStyle === null) {
      if (this.defaultFlowStyle !== null) node.flowStyle = this.defaultFlowStyle;
      else node.flowStyle = bestStyle;
    }
    return node;
  }

  /* -------------------------------------------------------------- *
   * Type dispatch — mirrors `type(data)` lookups in yaml_representers,
   * then the multi-representers for `type` and `object`.
   * -------------------------------------------------------------- */

  dispatch(data) {
    switch (typeName(data)) {
      case 'NoneType':
        return this.representNone();
      case 'str':
        return this.representStr(data);
      case 'bytes':
        return this.representBinary(data);
      case 'bool':
        return this.representBool(data);
      case 'int':
        return this.representInt(data);
      case 'float':
        return this.representFloat(data);
      case 'list':
        return this.representList(data);
      case 'tuple':
        return this.representTuple(data);
      case 'dict':
        return this.representDict(data);
      case 'set':
        return this.representSet(data);
      case 'frozenset':
        return this.representFrozenset(data);
      case 'complex':
        return this.representComplex(data);
      case 'range':
        return this.representRange(data);
      case 'slice':
        return this.representSlice(data);
      case 'builtin_function_or_method':
      case 'function':
        return this.representName(data);
      case 'ellipsis':
        // represent_object() unpacks the string 'Ellipsis' returned by
        // Ellipsis.__reduce_ex__(2) and blows up on `dict(dictitems)`.
        throw new PyError(
          'ValueError',
          'dictionary update sequence element #0 has length 1; 2 is required'
        );
      case 'object':
        if (data instanceof PyObject) return this.representObjectInstance(data);
        return this.representUndefined(data);
      default:
        return this.representUndefined(data);
    }
  }

  /* -------------------------------------------------------------- *
   * SafeRepresenter members
   * -------------------------------------------------------------- */

  representNone() {
    return this.representScalar(TAG.null, 'null');
  }

  representStr(data) {
    return this.representScalar(TAG.str, data);
  }

  representBinary(data) {
    return this.representScalar(TAG.binary, encodeBinary(data), '|');
  }

  representBool(data) {
    return this.representScalar(TAG.bool, data.value ? 'true' : 'false');
  }

  representInt(data) {
    return this.representScalar(TAG.int, data.toString());
  }

  representFloat(data) {
    let value;
    if (Number.isNaN(data)) {
      // `data != data or (data == 0.0 and data == 1.0)`
      value = '.nan';
    } else if (data === Infinity) {
      value = '.inf';
    } else if (data === -Infinity) {
      value = '-.inf';
    } else {
      value = pyFloatRepr(data).toLowerCase();
      // Transform '1e+16' into '1.0e+16' so it round-trips as a float.
      if (value.indexOf('.') < 0 && value.indexOf('e') >= 0) {
        const at = value.indexOf('e');
        value = value.slice(0, at) + '.0e' + value.slice(at + 1);
      }
    }
    return this.representScalar(TAG.float, value);
  }

  representList(data) {
    return this.representSequence(TAG.seq, data.items);
  }

  representDict(data) {
    return this.representMapping(TAG.map, data.entries());
  }

  /** `represent_set` builds `{item: None}` and represents that mapping. */
  representSet(data) {
    const pairs = data.values().map((item) => [item, PY_NONE]);
    return this.representMapping(TAG.set, pairs);
  }

  /* -------------------------------------------------------------- *
   * Representer (unsafe) members
   * -------------------------------------------------------------- */

  representComplex(data) {
    let text;
    if (data.im === 0) text = pyFloatRepr(data.re);
    else if (data.re === 0) text = pyFloatRepr(data.im) + 'j';
    else if (data.im > 0) text = pyFloatRepr(data.re) + '+' + pyFloatRepr(data.im) + 'j';
    else text = pyFloatRepr(data.re) + pyFloatRepr(data.im) + 'j';
    return this.representScalar(TAG.pythonComplex, text);
  }

  representTuple(data) {
    return this.representSequence(TAG.pythonTuple, data.items);
  }

  /**
   * `represent_name`: '%s.%s' % (data.__module__, data.__qualname__).
   * Builtins live in `builtins`; bound builtin methods report `__module__` of
   * None (verified: `'a'.upper` dumps as !!python/name:None.upper); a lambda
   * from eval'd source lives in `__main__`.
   */
  representName(data) {
    let name;
    if (data instanceof PyBoundMethod) name = 'None.' + data.name;
    else if (data instanceof PyBuiltin) name = 'builtins.' + data.name;
    else if (data instanceof PyFunction) name = '__main__.' + (data.name || '<lambda>');
    else return this.representUndefined(data);
    return this.representScalar(TAG.pythonNamePrefix + name, '');
  }

  /**
   * `represent_object` for the handful of builtins whose `__reduce_ex__(2)`
   * shape we know:  (callable, args) with an empty state becomes
   * `!!python/object/apply:<name>` wrapping the args as a sequence.
   */
  representFrozenset(data) {
    // frozenset.__reduce_ex__(2) -> (frozenset, ([items...],))
    return this.representSequence(TAG.pythonFrozenset, [new PyList(data.values())]);
  }

  representRange(data) {
    // range.__reduce_ex__(2) -> (range, (start, stop, step))
    return this.representSequence(TAG.pythonRange, [data.start, data.stop, data.step]);
  }

  representSlice(data) {
    // slice.__reduce_ex__(2) -> (slice, (start, stop, step)), None for absent
    const norm = (v) => (v === undefined || v === null ? PY_NONE : v);
    return this.representSequence(TAG.pythonSlice, [
      norm(data.start),
      norm(data.stop),
      norm(data.step),
    ]);
  }

  /**
   * `object()` reduces via `copyreg.__newobj__` with an empty state, so
   * represent_object takes the `python/object:<name>` + state mapping branch.
   */
  representObjectInstance(data) {
    const pairs = data.dict instanceof PyDict ? data.dict.entries() : [];
    return this.representMapping(TAG.pythonObjectPrefix + data.clsName, pairs);
  }

  representUndefined(data) {
    throw new PyError('RepresenterError', 'cannot represent an object: ' + typeName(data));
  }
}

export default Representer;

