/**
 * serializer.mjs — port of `yaml.serializer.Serializer`.
 *
 * Walks the node tree twice: `anchorNode` first, to discover which nodes are
 * referenced more than once (those get an anchor `idNNN`), then
 * `serializeNode`, which emits the events.  Both walks visit mapping keys
 * before their values, which is what fixes the anchor numbering.
 *
 * Node bookkeeping is by OBJECT IDENTITY (PyYAML uses plain dicts keyed by the
 * node, and Node has no __eq__/__hash__), so a Map/Set keyed by the node object
 * is an exact match.
 */

import { PyError } from '../pyvalues.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';
import { resolveScalar, resolveScalarDefault, resolveSequence, resolveMapping } from './resolver.mjs';
import {
  StreamStartEvent,
  StreamEndEvent,
  DocumentStartEvent,
  DocumentEndEvent,
  AliasEvent,
  ScalarEvent,
  SequenceStartEvent,
  SequenceEndEvent,
  MappingStartEvent,
  MappingEndEvent,
} from './events.mjs';

/** `Serializer.ANCHOR_TEMPLATE = 'id%03d'` */
function anchorName(id) {
  let digits = String(id);
  while (digits.length < 3) digits = '0' + digits;
  return 'id' + digits;
}

export class Serializer {
  /** @param {(event: object) => void} emitFn usually `emitter.emit` */
  constructor(emitFn) {
    this.emitFn = emitFn;
    // yaml.dump() defaults
    this.useEncoding = null;
    this.useExplicitStart = false;
    this.useExplicitEnd = false;
    this.useVersion = null;
    this.useTags = null;

    /** @type {Set<object>} nodes already written out */
    this.serializedNodes = new Set();
    /** @type {Map<object, string|null>} node -> anchor name (null = seen once) */
    this.anchors = new Map();
    this.lastAnchorId = 0;
    this.closed = null;
  }

  emit(event) {
    this.emitFn(event);
  }

  open() {
    if (this.closed === null) {
      this.emit(new StreamStartEvent(this.useEncoding));
      this.closed = false;
    } else if (this.closed) {
      throw new PyError('SerializerError', 'serializer is closed');
    } else {
      throw new PyError('SerializerError', 'serializer is already opened');
    }
  }

  close() {
    if (this.closed === null) {
      throw new PyError('SerializerError', 'serializer is not opened');
    } else if (!this.closed) {
      this.emit(new StreamEndEvent());
      this.closed = true;
    }
  }

  serialize(node) {
    if (this.closed === null) {
      throw new PyError('SerializerError', 'serializer is not opened');
    } else if (this.closed) {
      throw new PyError('SerializerError', 'serializer is closed');
    }
    this.emit(
      new DocumentStartEvent(this.useExplicitStart, this.useVersion, this.useTags)
    );
    this.anchorNode(node);
    this.serializeNode(node, null, null);
    this.emit(new DocumentEndEvent(this.useExplicitEnd));
    this.serializedNodes = new Set();
    this.anchors = new Map();
    this.lastAnchorId = 0;
  }

  /** First pass: a node seen twice becomes an anchor. */
  anchorNode(node) {
    if (this.anchors.has(node)) {
      if (this.anchors.get(node) === null) {
        this.anchors.set(node, this.generateAnchor(node));
      }
      return;
    }
    this.anchors.set(node, null);
    if (node instanceof SequenceNode) {
      for (const item of node.value) this.anchorNode(item);
    } else if (node instanceof MappingNode) {
      for (const [key, value] of node.value) {
        this.anchorNode(key);
        this.anchorNode(value);
      }
    }
  }

  generateAnchor() {
    this.lastAnchorId += 1;
    return anchorName(this.lastAnchorId);
  }

  serializeNode(node, parent, index) {
    const alias = this.anchors.get(node);
    if (this.serializedNodes.has(node)) {
      this.emit(new AliasEvent(alias));
      return;
    }
    this.serializedNodes.add(node);
    // descend_resolver()/ascend_resolver() are no-ops: there are no path
    // resolvers registered on the default Dumper.
    if (node instanceof ScalarNode) {
      // resolve(ScalarNode, value, (True, False)) vs (False, True)
      const detectedTag = resolveScalar(node.value);
      const defaultTag = resolveScalarDefault();
      const implicit = [node.tag === detectedTag, node.tag === defaultTag];
      this.emit(new ScalarEvent(alias, node.tag, implicit, node.value, node.style));
    } else if (node instanceof SequenceNode) {
      const implicit = node.tag === resolveSequence();
      this.emit(new SequenceStartEvent(alias, node.tag, implicit, node.flowStyle));
      let i = 0;
      for (const item of node.value) {
        this.serializeNode(item, node, i);
        i += 1;
      }
      this.emit(new SequenceEndEvent());
    } else if (node instanceof MappingNode) {
      const implicit = node.tag === resolveMapping();
      this.emit(new MappingStartEvent(alias, node.tag, implicit, node.flowStyle));
      for (const [key, value] of node.value) {
        this.serializeNode(key, node, null);
        this.serializeNode(value, node, key);
      }
      this.emit(new MappingEndEvent());
    }
  }
}

/**
 * dumper.mjs — the `yaml.dump(data)` facade.
 *
 * PyYAML's `dump_all` builds one Dumper (Emitter + Serializer + Representer +
 * Resolver mixed into a single object), then:
 *
 *     dumper.open()          -> StreamStartEvent
 *     dumper.represent(data) -> DocumentStart, node events, DocumentEnd
 *     dumper.close()         -> StreamEndEvent
 *
 * and returns the value of the string stream.  The three objects are separate
 * here, wired together by callbacks.
 */

import { Emitter } from './emitter.mjs';
import { Serializer } from './serializer.mjs';
import { Representer } from './representer.mjs';

/**
 * `yaml.dump(data)` with PyYAML's Dumper defaults (default_flow_style=False,
 * indent=2, width=80, allow_unicode=False, sort_keys=True, no explicit
 * start/end).  Note that the caller still has to add the newline that
 * `print()` contributes.
 *
 * @param {any} data a value from the pyvalues model
 * @returns {string}
 */
export function dump(data) {
  const chunks = [];
  const emitter = new Emitter({ write: (s) => chunks.push(s) });
  const serializer = new Serializer((event) => emitter.emit(event));
  const representer = new Representer(); // a fresh one per dump: aliases are per document

  serializer.open();
  // represent() builds the whole node tree before any document event is
  // emitted, exactly as in PyYAML's Dumper.represent().
  serializer.serialize(representer.represent(data));
  serializer.close();

  return chunks.join('');
}

