const AL = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
export function base64Encodebytes(bytes) {
  let out = '';
  let line = 0;
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i], b1 = bytes[i+1], b2 = bytes[i+2];
    out += AL[b0 >> 2];
    out += AL[((b0 & 3) << 4) | (b1 === undefined ? 0 : b1 >> 4)];
    out += b1 === undefined ? '=' : AL[((b1 & 15) << 2) | (b2 === undefined ? 0 : b2 >> 6)];
    out += b2 === undefined ? '=' : AL[b2 & 63];
    line += 4;
    if (line >= 76) { out += '\n'; line = 0; }
  }
  if (line > 0) out += '\n';
  return out;
}
