function show(label, data) {
  LOG.length = 0;
  try { dump(data); } catch (e) { console.log(label, 'ERR', e.pyName, e.pyMessage); return; }
  const parts = LOG.map((e) => {
    if (e.kind === 'Scalar') return 'S(' + (e.anchor||'-') + ',' + e.tag.replace('tag:yaml.org,2002:','!!') + ',[' + e.implicit + '],' + JSONish(e.value) + ',' + (e.style===null?'None':e.style) + ')';
    if (e.kind === 'Alias') return 'A(' + e.anchor + ')';
    if (e.kind === 'SequenceStart') return 'SEQ(' + (e.anchor||'-') + ',' + e.tag.replace('tag:yaml.org,2002:','!!') + ',' + e.implicit + ',' + e.flowStyle + ')';
